void Servo_Init_SPL(void)
{
    GPIO_InitTypeDef        GPIO_InitStructure;
    TIM_TimeBaseInitTypeDef TIM_TimeBaseStructure;
    TIM_OCInitTypeDef       TIM_OCInitStructure;

    // 1. Cấp xung nhịp cho GPIOA và TIM2
    RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA, ENABLE);
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM2, ENABLE);

    // 2. Cấu hình chân PA1 (TIM2_CH2): Alternate Function Push-Pull
    GPIO_InitStructure.GPIO_Pin   = GPIO_Pin_1;
    GPIO_InitStructure.GPIO_Mode  = GPIO_Mode_AF_PP;
    GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
    GPIO_Init(GPIOA, &GPIO_InitStructure);

    // 3. Khối Time-base 50Hz (Chu kỳ 20ms)
    TIM_TimeBaseStructure.TIM_Prescaler     = 72 - 1;    // Đếm mỗi 1us
    TIM_TimeBaseStructure.TIM_Period        = 20000 - 1; // 20000us = 20ms
    TIM_TimeBaseStructure.TIM_ClockDivision = TIM_CKD_DIV1;
    TIM_TimeBaseStructure.TIM_CounterMode   = TIM_CounterMode_Up;
    TIM_TimeBaseInit(TIM2, &TIM_TimeBaseStructure);

    // 4. Cấu hình Kênh 2 ngõ ra PWM Mode 1
    TIM_OCInitStructure.TIM_OCMode      = TIM_OCMode_PWM1;
    TIM_OCInitStructure.TIM_OutputState = TIM_OutputState_Enable;
    TIM_OCInitStructure.TIM_Pulse       = 1500; // Khởi tạo ở góc 90 độ (1.5ms)
    TIM_OCInitStructure.TIM_OCPolarity  = TIM_OCPolarity_High;
    TIM_OC2Init(TIM2, &TIM_OCInitStructure);

    // Bật bộ đệm Preload cho Channel 2
    TIM_OC2PreloadConfig(TIM2, TIM_OCPreload_Enable);
    TIM_ARRPreloadConfig(TIM2, ENABLE);

    // 5. Kích hoạt TIM2
    TIM_Cmd(TIM2, ENABLE);
}

// Hàm chuyển đổi góc quay từ 0 đến 180 độ thành giá trị nạp CCR2
void Servo_SetAngle(uint8_t angle)
{
    if (angle > 180) angle = 180;
    // Map từ [0 - 180] độ thành [1000 - 2000] us
    uint16_t pulse = 1000 + ((uint32_t)angle * 1000) / 180;
    TIM_SetCompare2(TIM2, pulse);
}

int main(void)
{
    Servo_Init_SPL();

    while (1)
    {
        Servo_SetAngle(0);   // Quay về 0 độ
        for (volatile int i = 0; i < 3000000; i++);

        Servo_SetAngle(90);  // Quay về 90 độ
        for (volatile int i = 0; i < 3000000; i++);

        Servo_SetAngle(180); // Quay về 180 độ
        for (volatile int i = 0; i < 3000000; i++);
    }
}

