#include "stm32f10x.h"

#define OLED_I2C_ADDR   0x78 // Địa chỉ 8-bit ghi của OLED SSD1306

void I2C1_Init_Register(void)
{
    // 1. Cấp clock cho GPIOB và I2C1 trên bus APB1
    RCC->APB2ENR |= (1 << 3); // IOPBEN = 1
    RCC->APB1ENR |= (1 << 21); // I2C1EN = 1

    // 2. Cấu hình PB6 (SCL) và PB7 (SDA): Alternate Function Open-Drain 50MHz
    // PB6: MODE6 = 11b, CNF6 = 11b (AF-OD)
    GPIOB->CRL &= ~(0x0F << 24);
    GPIOB->CRL |= (0x0F << 24);

    // PB7: MODE7 = 11b, CNF7 = 11b (AF-OD)
    GPIOB->CRL &= ~(0x0F << 28);
    GPIOB->CRL |= (0x0F << 28);

    // 3. Reset khối I2C1 phần cứng để giải phóng bus
    I2C1->CR1 |= (1 << 15);  // SWRST = 1
    for (volatile int i = 0; i < 100; i++);
    I2C1->CR1 &= ~(1 << 15); // SWRST = 0

    // 4. Cấu hình tần số bus PCLK1 = 36MHz vào thanh ghi I2C_CR2
    I2C1->CR2 = 36; // 36 MHz

    // 5. Cấu hình tốc độ Standard Mode 100kHz vào thanh ghi I2C_CCR
    // CCR = 36MHz / (2 * 100kHz) = 180 = 0x00B4
    I2C1->CCR = 180;

    // 6. Cấu hình thời gian sườn lên TRISE = 36 + 1 = 37
    I2C1->TRISE = 37;

    // 7. Kích hoạt bộ I2C1 (PE = 1)
    I2C1->CR1 |= (1 << 0);
}

// Phát điều kiện START
void I2C1_Start(void)
{
    I2C1->CR1 |= (1 << 8); // START = 1
    // Chờ cờ SB (Start Bit) được kéo lên 1 (EV5)
    while (!(I2C1->SR1 & (1 << 0)));
}

// Phát điều kiện STOP
void I2C1_Stop(void)
{
    I2C1->CR1 |= (1 << 9); // STOP = 1
}

// Gửi địa chỉ Slave (7-bit + R/W)
void I2C1_SendAddress(uint8_t address)
{
    I2C1->DR = address;
    // Chờ cờ ADDR (Address Sent) được kéo lên 1 (EV6)
    while (!(I2C1->SR1 & (1 << 1)));

    // XÓA CỜ ADDR: Đọc SR1 sau đó đọc SR2
    volatile uint32_t temp;
    temp = I2C1->SR1;
    temp = I2C1->SR2;
    (void)temp;
}

// Gửi 1 byte dữ liệu
void I2C1_WriteData(uint8_t data)
{
    // Chờ đệm truyền trống (TXE = 1)
    while (!(I2C1->SR1 & (1 << 7)));
    I2C1->DR = data;
    // Chờ cờ BTF (Byte Transfer Finished) báo byte đã phát xong
    while (!(I2C1->SR1 & (1 << 2)));
}

