void OLED_WriteCommand(uint8_t cmd)
{
    I2C1_Start();
    I2C1_SendAddress(OLED_I2C_ADDR);
    I2C1_WriteData(0x00); // Byte điều khiển: 0x00 = Lệnh Command
    I2C1_WriteData(cmd);
    I2C1_Stop();
}

