#include "stm32f10x.h"
#include <stdio.h>

#define CS_LOW()    (GPIOA->BRR = (1 << 4))
#define CS_HIGH()   (GPIOA->BSRR = (1 << 4))

void SPI1_Init_Register(void)
{
    // 1. Cấp xung clock cho GPIOA và SPI1 trên bus APB2
    RCC->APB2ENR |= (1 << 2) | (1 << 12);

    // 2. Cấu hình chân PA4 (CS): Output Push-Pull 50MHz
    GPIOA->CRL &= ~(0x0F << 16);
    GPIOA->CRL |= (0x03 << 16);
    CS_HIGH(); // Mặc định không chọn chip (CS = 1)

    // 3. Cấu hình PA5 (SCK) và PA7 (MOSI): Alternate Function Output Push-Pull 50MHz
    GPIOA->CRL &= ~((0x0F << 20) | (0x0F << 28));
    GPIOA->CRL |= (0x0B << 20) | (0x0B << 28); // AF_PP 50MHz

    // 4. Cấu hình PA6 (MISO): Input with Pull-Up
    GPIOA->CRL &= ~(0x0F << 24);
    GPIOA->CRL |= (0x08 << 24); // Input Pull-up
    GPIOA->ODR |= (1 << 6);

    // 5. Cấu hình khối SPI1 trên thanh ghi SPI_CR1:
    // - Tốc độ: PCLK2 (72MHz) / 8 = 9MHz (BR[2:0] = 010b)
    // - Chế độ Master: MSTR = 1
    // - SPI Mode 0: CPOL = 0, CPHA = 0
    // - Khung truyền 8-bit: DFF = 0
    // - Quản lý chân NSS bằng phần mềm: SSM = 1, SSI = 1
    SPI1->CR1 = (0x02 << 3) | // BR = /8 (9MHz)
                (1 << 2)     | // MSTR = 1
                (1 << 9)     | // SSM = 1
                (1 << 8);      // SSI = 1

    // 6. Kích hoạt bộ SPI1 (SPE = 1)
    SPI1->CR1 |= (1 << 6);
}

// Hàm truyền và nhận đồng thời 1 byte dữ liệu qua SPI1
uint8_t SPI1_Transfer(uint8_t data)
{
    // Chờ bộ đệm truyền trống (TXE = 1)
    while (!(SPI1->SR & (1 << 1)));
    SPI1->DR = data;

    // Chờ bộ đệm nhận có dữ liệu về (RXNE = 1)
    while (!(SPI1->SR & (1 << 0)));
    return (uint8_t)(SPI1->DR & 0xFF);
}

// Đọc mã nhận dạng chip JEDEC ID của W25Q64
uint32_t W25Q64_ReadID(void)
{
    uint32_t id = 0;
    uint8_t byte1, byte2, byte3;

    CS_LOW(); // Bắt đầu phiên truyền

    // Gửi mã lệnh đọc JEDEC ID: 0x9F
    SPI1_Transfer(0x9F);

    // Gửi Dummy byte 0xFF để nhận về 3 byte mã ID
    byte1 = SPI1_Transfer(0xFF); // Manufacturer ID (Winbond = 0xEF)
    byte2 = SPI1_Transfer(0xFF); // Memory Type (0x40)
    byte3 = SPI1_Transfer(0xFF); // Capacity (64Mbit = 0x17)

    CS_HIGH(); // Kết thúc phiên truyền

    id = (byte1 << 16) | (byte2 << 8) | byte3;
    return id;
}

