#include "stm32f10x.h"
#include <string.h>

char tx_message[] = "Hello World! This long text is sent via UART1 DMA with 0% CPU usage!\r\n";

void UART1_DMA_Init(void)
{
    // 1. Cấp clock cho GPIOA, USART1 và khối DMA1 trên bus AHB
    RCC->APB2ENR |= (1 << 2) | (1 << 14); // IOPAEN = 1, USART1EN = 1
    RCC->AHBENR  |= (1 << 0);             // DMA1EN = 1 (Bật clock DMA1)

    // 2. Cấu hình chân PA9 (TX): Alternate Function Push-Pull 50MHz
    GPIOA->CRH &= ~(0x0F << 4);
    GPIOA->CRH |= (0x0B << 4);

    // 3. Cấu hình Baudrate USART1 = 115200 (72MHz)
    USART1->BRR = 72000000 / 115200;
    USART1->CR1 |= (1 << 3) | (1 << 13); // TE = 1, UE = 1

    // 4. Cho phép USART1 phát yêu cầu truyền DMA (DMAT = 1 trong USART_CR3)
    USART1->CR3 |= (1 << 7); // DMAT = 1

    // 5. Cấu hình DMA1 Channel 4 (chuyên trách USART1_TX):
    DMA1_Channel4->CCR = 0; // Tắt kênh trước khi cấu hình

    // Địa chỉ ngoại vi: Thanh ghi dữ liệu USART1_DR (0x40013804)
    DMA1_Channel4->CPAR = (uint32_t)&(USART1->DR);

    // Địa chỉ bộ nhớ RAM: Con trỏ trỏ tới chuỗi ký tự
    DMA1_Channel4->CMAR = (uint32_t)tx_message;

    // Số lượng byte cần truyền
    DMA1_Channel4->CNDTR = strlen(tx_message);

    // Cấu hình thanh ghi CCR4:
    // - DIR = 1: Đọc từ RAM ra Ngoại vi (Memory to Peripheral)
    // - MINC = 1: Tự động tăng địa chỉ ô nhớ RAM
    // - PINC = 0: Không tăng địa chỉ ngoại vi
    // - PSIZE = 00b (8-bit), MSIZE = 00b (8-bit)
    // - PL = 10b (Mức ưu tiên High)
    DMA1_Channel4->CCR = (1 << 4) | (1 << 7) | (0x02 << 12);
}

void UART1_DMA_Send(void)
{
    // Tắt kênh để nạp lại số lượng dữ liệu
    DMA1_Channel4->CCR &= ~(1 << 0); // EN = 0

    // Xóa cờ hoàn thành truyền cũ trong DMA_IFCR
    DMA1->IFCR |= (1 << 13); // CTCIF4 = 1

    // Nạp lại độ dài chuỗi
    DMA1_Channel4->CNDTR = strlen(tx_message);

    // Bật kênh DMA để bắt đầu tự động truyền
    DMA1_Channel4->CCR |= (1 << 0); // EN = 1
}

int main(void)
{
    UART1_DMA_Init();

    while (1)
    {
        UART1_DMA_Send();

        // CPU hoàn toàn rảnh rỗi chớp tắt LED PC13 mà không bị nghẽn
        for (volatile int i = 0; i < 2000000; i++);
    }
}

