#include <stdio.h>
#include "FreeRTOS.h"
#include "task.h"
#include "event_groups.h"
#include "timers.h"

// Định nghĩa các bit sự kiện
#define BIT_SENSOR_READY   (1 << 0) // Bit 0
#define BIT_FLASH_READY    (1 << 1) // Bit 1
#define ALL_SYSTEMS_BITS   (BIT_SENSOR_READY | BIT_FLASH_READY)

EventGroupHandle_t xSystemEventGroup;
TimerHandle_t      xLedTimer;
TaskHandle_t       xAlertTaskHandle = NULL;

// 1. Hàm Callback của Software Timer: Chớp tắt LED PC13 mỗi 500ms
void vLedTimerCallback(TimerHandle_t xTimer)
{
    GPIOC->ODR ^= (1 << 13); // Đảo trạng thái LED PC13
}

// 2. Task Giả Lập Khởi Động Cảm Biến
void vTaskInitSensor(void *pvParameters)
{
    // Giả lập thời gian nạp cảm biến mất 1 giây
    vTaskDelay(pdMS_TO_TICKS(1000));
    printf("[Init] Sensor Hardware is READY!\r\n");

    // Bật bit 0 trong Event Group
    xEventGroupSetBits(xSystemEventGroup, BIT_SENSOR_READY);

    vTaskDelete(NULL); // Hoàn thành nhiệm vụ, tự xóa Task
}

// 3. Task Giả Lập Khởi Động Bộ Nhớ Flash
void vTaskInitFlash(void *pvParameters)
{
    // Giả lập thời gian kiểm tra Flash mất 2 giây
    vTaskDelay(pdMS_TO_TICKS(2000));
    printf("[Init] Flash Memory is READY!\r\n");

    // Bật bit 1 trong Event Group
    xEventGroupSetBits(xSystemEventGroup, BIT_FLASH_READY);

    vTaskDelete(NULL); // Tự xóa Task
}

// 4. Task Quản Lý Hệ Thống: Chờ ĐỦ 2 ĐIỀU KIỆN MỚI CHẠY (Logic AND)
void vTaskSystemManager(void *pvParameters)
{
    EventBits_t uxBits;

    printf("[Manager] Waiting for all subsystems to initialize...\r\n");

    // =========================================================================
    // HÀM CHỜ EVENT GROUP: xEventGroupWaitBits()
    // Tham số:
    // 1. Handle của Event Group
    // 2. Các bit cần chờ (ALL_SYSTEMS_BITS)
    // 3. pdTRUE: Xóa các bit về 0 sau khi chờ xong
    // 4. pdTRUE: Chờ TẤT CẢ các bit (Logic AND)
    // 5. portMAX_DELAY: Chờ vô thời hạn
    // =========================================================================
    uxBits = xEventGroupWaitBits(xSystemEventGroup,
                                ALL_SYSTEMS_BITS,
                                pdTRUE,
                                pdTRUE,
                                portMAX_DELAY);

    if ((uxBits & ALL_SYSTEMS_BITS) == ALL_SYSTEMS_BITS)
    {
        printf(">>> [SUCCESS] ALL SUBSYSTEMS READY! SYSTEM OPERATIONAL! <<<\r\n");
    }

    while (1)
    {
        // Hệ thống chính vận hành ở đây
        vTaskDelay(pdMS_TO_TICKS(1000));
    }
}

