    // Tổng số time quanta (tq) = 1 + 12 + 5 = 18 tq
    // Baudrate = 36,000,000 / (4 * 18) = 500,000 bps = 500 kbps!
    CAN1->BTR = 0;
    CAN1->BTR |= (4 - 1)  << 0;   // BRP[9:0] = 3
    CAN1->BTR |= (12 - 1) << 16;  // TS1[3:0] = 11
    CAN1->BTR |= (5 - 1)  << 20;  // TS2[2:0] = 4
    CAN1->BTR |= (1 - 1)  << 24;  // SJW[1:0] = 0

    // THỬ NGHIỆM: Bật chế độ Loopback để test nội bộ không cần dây nối
    // (Bỏ dòng này khi chạy với module TJA1050 thật)
    CAN1->BTR |= (1 << 30); // LBKM = 1 (Loopback Mode)

    // 7. YÊU CẦU THOÁT CHẾ ĐỘ KHỞI TẠO, BẮT ĐẦU HOẠT ĐỘNG
    CAN1->MCR &= ~(1 << 0); // INRQ = 0
    while (CAN1->MSR & (1 << 0)); // Chờ INAK = 0

    // 8. CẤU HÌNH BỘ LỌC PHẦN CỨNG (FILTER BANK 0) CHO PHÉP NHẬN TẤT CẢ ID
    CAN1->FMR |= (1 << 0);  // FINIT = 1 (Vào chế độ cấu hình bộ lọc)
    CAN1->FA1R &= ~(1 << 0); // Vô hiệu hóa Filter 0 để sửa đổi

    CAN1->FS1R |= (1 << 0); // Độ rộng 32-bit (1 Single 32-bit filter)
    CAN1->FM1R &= ~(1 << 0); // Chế độ Mask Mode
    CAN1->sFilterRegister[0].FR1 = 0x00000000; // ID = 0
    CAN1->sFilterRegister[0].FR2 = 0x00000000; // Mask = 0 (Chấp nhận tất cả ID)
    CAN1->FFA1R &= ~(1 << 0); // Gán vào FIFO 0

    CAN1->FA1R |= (1 << 0);  // Kích hoạt lại Filter 0
    CAN1->FMR &= ~(1 << 0);  // FI
// ... (xem tiep trong bai giang)

