    printf("\r\n   Program Counter (PC) = 0x%08X (CRASH LOCATION)", pc);
    printf("\r\n   Link Register    (LR) = 0x%08X (CALLER FUNCTION)", lr);
    printf("\r\n   Program Status  (xPSR)= 0x%08X", psr);
    printf("\r\n>> GENERAL PURPOSE REGISTERS:");
    printf("\r\n   R0 = 0x%08X | R1 = 0x%08X | R2 = 0x%08X | R3 = 0x%08X", r0, r1, r2, r3);
    printf("\r\n   R12= 0x%08X", r12);
    printf("\r\n>> SYSTEM FAULT STATUS:");
    printf("\r\n   CFSR = 0x%08X", cfsr);
    printf("\r\n   HFSR = 0x%08X", hfsr);

    // Kiểm tra xem có địa chỉ truy cập cấm trong BFAR không
    if (cfsr & (1 << 15)) // BFARVALID = Bit 15 của CFSR
    {
        printf("\r\n   BusFault Address (BFAR) = 0x%08X (ILLEGAL ACCESS MEMORY)", bfar);
    }
    printf("\r\n==================================================\r\n");

    // Dừng CPU để kỹ sư cắm que nạp ST-Link vào quan sát
    __BKPT(0); // Điểm dừng Breakpoint phần cứng
    while (1);
}

// Đoạn mã Assembly đón đầu hàm ngắt HardFault_Handler
// (Thay thế hàm HardFault_Handler rỗng trong file stm32f10x_it.c)
__asm void HardFault_Handler(void)
{
    // Kiểm tra bit 2 của thanh ghi LR (EXC_RETURN)
    // Nếu bit 2 = 0: Ngăn xếp sử dụng là MSP
    // Nếu bit 2 = 1: Ngăn xếp sử dụng là PSP (Đang chạy trong Task FreeRTOS)
    TST LR, #4
    ITE EQ
    MRSEQ R0, MSP
    MRSNE R0, PSP
    B __cpp(HardFault_Decoder_C)
}
